// The structural path of an object depends on the order in which the
// references of its referrer are followed. Ruby follows the to-one attributes,
// then the to-many ones, then the references by keys, each in attribute order
// (a class' own attributes before its superclass').
//
// reference_attributes.json holds that order for every class of xcodeproj
// (regenerated by reference_attributes.rb next to it); this test checks that
// the Dart classes expose the same references in the same order, which
// `UuidGenerator.structuralPaths` relies on. Fixtures cover only the classes
// Flutter projects use, this covers all of them.

import 'dart:convert';
import 'dart:io';

import 'package:dart_xcodeproj/src/object/abstract_object.dart';
import 'package:dart_xcodeproj/src/object/isa_registry.dart';
import 'package:dart_xcodeproj/src/project/xcode_project.dart';
import 'package:test/test.dart';

const _file = 'test/fixtures/predictabilized/reference_attributes.json';

/// To-one attributes Ruby has and the Dart classes do not model (yet): the
/// attribute is not read from a project, so it never takes part in a path.
const _unmodeled = {
  'PBXTargetDependency': {'productRef'},
};

/// The plist keys of [object]'s to-one attributes, in the order they are
/// followed.
List<String> _toOne(AbstractObject object) {
  final references = object.referenceAttributes.toSet();
  final toMany = object.toManyAttributeKeys.toSet();
  return [
    for (final key in object.attributeOrder)
      if (references.contains(key) && !toMany.contains(key)) key,
  ];
}

void main() {
  // The groups below are made from the registry, which has to be filled first.
  registerPhase3Types();
  registerPhase4Types();

  late XcodeProject project;
  late Map<String, dynamic> ruby;

  setUpAll(() async {
    final tmp = Directory.systemTemp.createTempSync('reference_attributes_');
    addTearDown(() => tmp.deleteSync(recursive: true));
    project = await XcodeProject.create('${tmp.path}/Test.xcodeproj');
    ruby = jsonDecode(File(_file).readAsStringSync()) as Map<String, dynamic>;
  });

  test('every class Dart implements is known to Ruby', () {
    expect(ruby.keys, containsAll(isaRegistry.keys));
  });

  for (final isa in isaRegistry.keys.toList()..sort()) {
    group(isa, () {
      late AbstractObject object;
      late Map<String, dynamic> expected;

      setUp(() {
        object = isaRegistry[isa]!(project, 'UUID');
        expected = ruby[isa] as Map<String, dynamic>;
      });

      test('has the to-one references of Ruby, in order', () {
        final unmodeled = _unmodeled[isa] ?? const <String>{};
        expect(
          _toOne(object),
          equals([
            for (final key in expected['toOne'] as List)
              if (!unmodeled.contains(key)) key,
          ]),
        );
      });

      test('has the to-many references of Ruby, in order', () {
        expect(object.toManyAttributeKeys, equals(expected['toMany']));
      });

      test('has the references by keys of Ruby, in order', () {
        expect(
          object.referencesByKeysAttributeKeys,
          equals(expected['referencesByKeys']),
        );
      });

      test('names as many to-many keys as it has to-many lists', () {
        expect(
          object.toManyAttributeKeys,
          hasLength(object.toManyAttributes.length),
        );
        expect(
          object.referencesByKeysAttributeKeys,
          hasLength(object.referencesByKeysAttributes.length),
        );
      });
    });
  }
}
